Example 3: Simple calculator program using C# switch Statement
using
System;
namespace
Conditional
{
class
SwitchCase
{
public
static
void
Main
(
string
[] args
)
{
char
op;
double
first, second, result;
Console.Write(
"Enter first number: "
);
first = Convert.ToDouble(Console.ReadLine());
Console.Write(
"Enter second number: "
);
second = Convert.ToDouble(Console.ReadLine());
Console.Write(
"Enter operator (+, -, *, /): "
);
op = (
char
)Console.Read();
switch
(op)
{
case
'+'
:
result = first + second;
Console.WriteLine(
"{0} + {1} = {2}"
, first, second, result);
break
;
case
'-'
:
result = first - second;
Console.WriteLine(
"{0} - {1} = {2}"
, first, second, result);
break
;
case
'*'
:
result = first * second;
Console.WriteLine(
"{0} * {1} = {2}"
, first, second, result);
break
;
case
'/'
:
result = first / second;
Console.WriteLine(
"{0} / {1} = {2}"
, first, second, result);
break
;
default
:
Console.WriteLine(
"Invalid Operator"
);
break
;
